    # Generate all possible (X, Y, Z)
    # X = x+y, Y = y+z, Z = z+x where x, y, z in {0, ..., 9}
    T = []
    for x in range(10):
        for y in range(10):
            for z in range(10):
                T.append((x+y, y+z, z+x))

    # Remove duplicates (though (X, Y, Z) should be unique for each (x, y, z))
    T = list(set(T))
    print(f"Number of unique (X, Y, Z): {len(T)}")

    # Generate all possible questions (a, b, c)
    # Each question is (a, b, c) where a, b, c in {0, ..., 9}
    # Each question gives V = |X-A| + |Y-B| + |Z-C| where A=a+b, B=b+c, C=c+a
    questions = []
    for a in range(10):
        for b in range(10):
            for c in range(10):
                questions.append((a, b, c))

    # Precompute the result of each question for each (X, Y, Z)
    # results[q_idx] = [V_0, V_1, ..., V_{len(T)-1}]
    results = []
    for a, b, c in questions:
        A, B, C = a+b, b+c, c+a
        res = []
        for X, Y, Z in T:
            res.append(abs(X-A) + abs(Y-B) + abs(Z-C))
        results.append(res)

    # Check if k=1 is enough
    # A question is enough if all results are unique
    for res in results:
        if len(set(res)) == len(T):
            print("k=1 is enough")
            return 1

    # Check if k=2 is enough
    # For each question q1, partition T into groups
    # For each group, check if there is a question q2 that distinguishes all elements in it
    for q1_idx in range(len(results)):
        res1 = results[q1_idx]
        groups = {}
        for i, v1 in enumerate(res1):
            if v1 not in groups:
                groups[v1] = []
            groups[v1].append(i)

        possible = True
        for v1 in groups:
            group = groups[v1]
            if len(group) <= 1:
                continue

            # Check if any q2 distinguishes all elements in this group
            found_q2 = False
            for q2_idx in range(len(results)):
                res2 = results[q2_idx]
                vals_in_group = [res2[i] for i in group]
                if len(set(vals_in_group)) == len(group):
                    found_q2 = True
                    break

            if not found_q2:
                possible = False
                break

        if possible:
            print("k=2 is enough")
            return 2

    # If not 2, check k=3
    # This might be slow. Let's see if it's 2 first.
    return 3

